 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>

   <main id="main-content">
     <section class="card" aria-labelledby="page-title">
       <h1 id="page-title">Agree to the terms</h1>
       <p class="lede">Review the terms of use and confirm your agreement to continue.</p>

       <form id="consent-form" novalidate>
         <div class="form-field">
           <div class="checkbox-row">
             <input
               type="checkbox"
               id="agree-terms"
               name="agreeTerms"
               required
               aria-describedby="agree-help form-status"
             />
             <div>
               <label for="agree-terms">
                 I agree to the terms of use <span class="required-indicator" aria-hidden="true">*</span>
               </label>
               <p class="helper-text" id="agree-help">You must agree before submitting this form.</p>
             </div>
           </div>
         </div>

         <p class="status" id="form-status" aria-live="polite"></p>

         <div class="actions">
           <button type="submit">Submit</button>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('consent-form');
     const checkbox = document.getElementById('agree-terms');
     const status = document.getElementById('form-status');

     form.addEventListener('submit', (event) => {
       if (!checkbox.checked) {
         event.preventDefault();
         checkbox.setAttribute('aria-invalid', 'true');
         status.textContent = 'Please agree to the terms of use before submitting.';
         checkbox.focus();
         return;
       }

       checkbox.removeAttribute('aria-invalid');
       status.textContent = 'Thanks. Your consent has been recorded.';
       event.preventDefault();
     });

     checkbox.addEventListener('input', () => {
       if (checkbox.checked) {
         checkbox.removeAttribute('aria-invalid');
         status.textContent = '';
       }
     });
   </script>
